  "policy": "Regulation (EU) 2024/1991 on nature restoration",
  "policyShort": "Nature Restoration Regulation",
  "docType": "Regulation",
  "area": "Climate",
  "num": 10,
  "order": 2,
  "text": "Member States shall ensure that the condition is known of the following areas: (a) by 2030, for at least 50 % of the area distributed over all habitat types in groups 1 to 6 listed in Annex II; (b) by 2040, for all areas of the habitat types in groups 1 to 6 listed in Annex II; (c) by 2040, for at least 50 % of the area distributed over all habitat types in group 7 listed in Annex II; (d) by 2050, for all areas of the habitat types in group 7 listed in Annex II.",
  "short": "Condition of marine habitats mapped: half by 2030, all main habitat groups by 2040",
  "provision": "Article 5(7), points (a)–(d) — Restoration of marine ecosystems (condition known)",
  "label": "target",
  "obligation": "mandatory",
  "targetType": "quantitative",
  "timeline": "by 2030",
